 static void RepairLibraryCovers(){var app=new System.Windows.Application();var shelf=new Shelf(true);shelf.Scan();var results=new List<object>();foreach(var game in shelf.games.Where(g=>!HasCover(g.Cover)||g.OriginalName=="《赤痕·：夜之仪式》"&&!File.Exists(g.Cover+".manual")&&(!File.Exists(g.Cover+".appid")||File.ReadAllText(g.Cover+".appid").Trim()!="692850"))){try{string originalCover=game.Cover;bool replace=HasCover(originalCover);if(replace)game.Cover=originalCover+".corrected.jpg";bool ok=Fetch(game);if(replace&&ok){WriteCover(originalCover,File.ReadAllBytes(game.Cover));foreach(string side in new[]{".title",".appid"})if(File.Exists(game.Cover+side))File.Copy(game.Cover+side,originalCover+side,true);game.Cover=originalCover;}results.Add(new{Name=game.OriginalName,Success=ok,Error=""});}catch(Exception ex){results.Add(new{Name=game.OriginalName,Success=false,Error=ex.Message});}}File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"cover-repair.json"),json.Serialize(results));shelf.Close();app.Shutdown();}
