 static WebClient Client(){var w=new TimedClient();w.Encoding=Encoding.UTF8;w.Headers["User-Agent"]="GameShelf/1.0";return w;}
 static string ExternalCover(string name){string key=Norm(name);if(key=="英雄联盟"||key=="leagueoflegends")return "https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/565197caf987af4e4da307df6e2b235a28714736-837x469.jpg";if(key.StartsWith("血源诅咒")||key.StartsWith("bloodborne"))return "https://image.api.playstation.com/vulcan/img/rnd/202011/0713/WSZqsrnejjt85wYmUqeBQvMQ.png";if((key.Contains("植物大战僵尸")&&key.Contains("杂交"))||key.StartsWith("pvzhybrid"))return "https://img.3dmgame.com/uploads/images/xiaz/20240705/1720184439_754180.jpg";return null;}
 static bool Fetch(Game g,bool metadataOnly=false){if(Norm(g.OriginalName).StartsWith("yuzu")&&!HasCover(g.Cover))return BuiltinCover(g);if(metadataOnly&&File.Exists(g.Cover+".title"))return true;if(!metadataOnly&&HasCover(g.Cover))return true;ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;string external=ExternalCover(g.OriginalName);if(external!=null){if(metadataOnly){File.WriteAllText(g.Cover+".title",g.Name);return true;}using(var client=Client()){byte[] data=client.DownloadData(external);using(var ms=new MemoryStream(data)){var frame=BitmapFrame.Create(ms,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);if(frame.PixelWidth<100||frame.PixelHeight<100)return false;}WriteCover(g.Cover,data);File.WriteAllText(g.Cover+".source",external);File.WriteAllText(g.Cover+".fit","1");File.WriteAllText(g.Cover+".title",g.Name);File.Delete(g.Cover+".retry");return true;}}string app=null,tiny=null;string idFile=g.Cover+".appid";if(File.Exists(idFile))app=File.ReadAllText(idFile).Trim();else if(knownIds.ContainsKey(g.OriginalName))app=knownIds[g.OriginalName];
  using(var w=Client()){
   if(app==null){string query=aliases.ContainsKey(g.OriginalName)?aliases[g.OriginalName]:g.OriginalName;Dictionary<string,object> best=null;double score=0;
    foreach(var cc in new[]{"CN","US"}){var data=json.DeserializeObject(w.DownloadString("https://store.steampowered.com/api/storesearch/?term="+Uri.EscapeDataString(query)+"&l="+(Regex.IsMatch(query,@"[\u4e00-\u9fff]")?"schinese":"english")+"&cc="+cc)) as Dictionary<string,object>;if(data==null||!data.ContainsKey("items"))continue;var items=data["items"] as object[];if(items==null)continue;
     foreach(var obj in items){var it=obj as Dictionary<string,object>;var n=Norm(it["name"].ToString());var q=Norm(query);double s=n==q?1:(n.StartsWith(q)||q.StartsWith(n))?0.87:0;if(IsSupplement(it["name"].ToString(),query))s=0;if(s>score){score=s;best=it;}}if(best!=null)break;
    }if(best==null)return false;app=best["id"].ToString();if(best.ContainsKey("tiny_image"))tiny=best["tiny_image"].ToString();
   }
   File.WriteAllText(idFile,app);
   Dictionary<string,object> details=null;var modernUrls=new List<string>();
   try{string input="{\"ids\":[{\"appid\":"+app+"}],\"context\":{\"language\":\"schinese\",\"country_code\":\"US\"},\"data_request\":{\"include_assets\":true}}";var result=json.DeserializeObject(w.DownloadString("https://api.steampowered.com/IStoreBrowseService/GetItems/v1/?input_json="+Uri.EscapeDataString(input))) as Dictionary<string,object>;var response=result["response"] as Dictionary<string,object>;var items=response["store_items"] as object[];
    if(items!=null&&items.Length>0){var item=items[0] as Dictionary<string,object>;if(item.ContainsKey("name"))details=item;if(item.ContainsKey("assets")){var assets=item["assets"] as Dictionary<string,object>;if(assets!=null&&assets.ContainsKey("asset_url_format"))foreach(var key in new[]{"library_capsule","library_capsule_2x","hero_capsule","header"})if(assets.ContainsKey(key)&&!string.IsNullOrEmpty(assets[key].ToString()))modernUrls.Add("https://shared.akamai.steamstatic.com/store_item_assets/"+assets["asset_url_format"].ToString().Replace("${FILENAME}",assets[key].ToString()));}}
   }catch{}
   try{if(details==null){var response=json.DeserializeObject(w.DownloadString("https://store.steampowered.com/api/appdetails?appids="+app+"&l=schinese&cc=US")) as Dictionary<string,object>;var item=response[app] as Dictionary<string,object>;if(item.ContainsKey("data"))details=item["data"] as Dictionary<string,object>;}
    File.WriteAllText(g.Cover+".title",details!=null&&details.ContainsKey("name")?details["name"].ToString():g.OriginalName);
   }catch{if(!File.Exists(g.Cover+".title"))File.WriteAllText(g.Cover+".title",g.OriginalName);}
   if(metadataOnly||HasCover(g.Cover))return true;
   var urls=modernUrls;urls.Add("https://cdn.akamai.steamstatic.com/steam/apps/"+app+"/library_600x900.jpg");urls.Add("https://cdn.akamai.steamstatic.com/steam/apps/"+app+"/header.jpg");
   if(details!=null){foreach(var key in new[]{"header_image","capsule_image"})if(details.ContainsKey(key))urls.Add(details[key].ToString());}if(tiny!=null)urls.Add(tiny);
